presentacion_id": 1}, {"id": 3, "hash": "60d9297410327a85604b77eff345d14198667f6b461287ef4db8461a82d79156", "tipo": "escrito", "uuid": "23360d4a-0095-46e1-9a84-b8a0d7856519", "estado": "definitivo", "numero": null, "titulo": "COMPROMISO TRÁNSITO INFRACTOR PV", "creado_por": "Operador Mesa", "firmado_at": null, "archivo_raw": null, "firmado_por": null, "observacion": null, "date_created": 1791218919626, "date_updated": 1791218919681, "fecha_numero": null, "modo_edicion": "campos", "plantilla_id": 16, "valores_json": "{\"c1\":\"20000\",\"c2\":\"0\",\"c3\":\"0\",\"c4\":\"1\",\"c5\":\"10\"}", "infraccion_id": 6, "archivo_nombre": null, "contenido_html": "<p style=\"text-align:right\">Los Polvorines, 9/10/2026</p><p style=\"text-align:center\"><strong>DIRECCIÓN DE FALTAS</strong></p><p style=\"text-align:center\"><strong>Ref. Acta de Infracción Nº T-001006 / Legajo Nº 2006/2026</strong></p><p style=\"text-align:center\"><strong>Dominio A123BCD</strong></p><p style=\"text-align:justify\"><strong>Sr. / Sra. Valeria Suárez, DNI Nº 30111222</strong>, constituyendo domicilio en la calle <strong>Belgrano</strong> Nº <strong>2472</strong> de <strong>Grand Bourg</strong>, partido de <strong>Malvinas Argentinas</strong>, provincia de <strong>Buenos Aires</strong>, en el día de la fecha, comparezco ante la Dirección de Faltas de la Municipalidad de Malvinas Argentinas y me notifico del <strong>PAGO VOLUNTARIO</strong> de $ 20.000,00en concepto de multa por las infracciones detalladas en el <strong>Acta de Infracción Nº T-001006: Ordenanza 261/2022 Art. 45 (Exceder la velocidad máxima). </strong>Asimismo, me comprometo a abonar los montos correspondientes a servicios varios en concepto de <strong>ESTADÍA</strong> de $ 0,00y de <strong>ACARREO</strong> de $0,00El monto detallado anteriormente me comprometo a abonarlo en 1cuotas mensuales y consecutivas, con un plazo para abonar la primera cuota dentro de los próximos 10días hábiles.</p><p style=\"text-align:justify\">Por otra parte, se deja constancia que, juntamente con el importe de las infracciones constatadas, se debe realizar el pago de <strong>PESOS CINCO MIL ($5.000)</strong> en concepto de sellado por actuaciones administrativas iniciadas, conforme lo establece la Ordenanza Fiscal y Tarifaria vigente, que será abonado por única vez.</p><p style=\"text-align:justify\">En este acto tomo conocimiento que el beneficio del pago voluntario al que me acogí tendrá un plazo de treinta (30) días. Finalizado el plazo, y no existiendo constancias de pago o allanamiento, tendré un plazo de quince (15) días, contados a partir del día siguiente al vencimiento del plazo para el pago voluntario, para presentar mi descargo y ofrecer la prueba que a derecho considere, pudiendo ser asistido por un letrado, todo ello bajo el apercibimiento de ser declarado rebelde y resolverse el Acta de Infracción N° T-001006 con las constancias obrantes en el Legajo N° 2006/2026.</p><p style=\"text-align:justify\">La falta de pago en tiempo y forma producirá la extinción automática del presente plan, sin mediar notificación alguna por parte de esta Dirección pasando las actuaciones a resolución mediante fallo administrativo. -</p><p style=\"text-align:justify\"><strong>Firma: __________________________________________________</strong></p><p style=\"text-align:justify\"><strong>Aclaración: ______________________________________________</strong></p><p style=\"text-align:justify\"><strong>D.N.I. Nº: _______________________________________________</strong></p><p style=\"text-align:justify\"><strong>Teléfono de contacto: _____________________________________</strong></p><p><strong>Constituyo domicilio electrónico: ___________________________</strong>San Martín 2670. Ciudad de Los Polvorines. C.P.: 1613 - Tel.: 4660-9000 INT. 2079</p>", "presentacion_id": null}, {"id": 4, "hash": null, "tipo": "adjunto", "uuid": "37c6be00-5d9f-4de3-96ff-e61b4f39624a", "estado": "definitivo", "numero": null, "titulo": "DNI frente · Solicitud de